/-- [The source iid object](goal) is defined from [the supplied inputs](hyp:P,nS,nT). -/
def SourceIid (P : TransportLaw) (nS nT : ℕ) : Prop :=
  (dataLaw P nS nT).map Prod.fst = Measure.pi (fun _ : Fin nS => sourceObsLaw P)

