/-- [The target iid object](goal) is defined from [the supplied inputs](hyp:P,nS,nT). -/
def TargetIid (P : TransportLaw) (nS nT : ℕ) : Prop :=
  (dataLaw P nS nT).map Prod.snd = Measure.pi (fun _ : Fin nT => targetXLaw P)

