/-- [The source density holder object](goal) is defined from [the supplied inputs](hyp:L,P). -/
def SourceDensityHolder (L : ℝ) (P : TransportLaw) : Prop :=
  HolderOn P.fS L -- @realizes f_{\mathrm S}(Hölder radius L)

