/-- [The block size object](goal) is defined from [the supplied inputs](hyp:n,b). -/
def blockSize (n : ℕ) (b : Fin 4) : ℕ :=
  (b.val + 1) * n / 4 - b.val * n / 4 -- @realizes m_b(exact block size)
